{"cards": [{"node_code": "N_779491a25bf9d447", "definition": "研究航空运输服务岗位（如客舱乘务、地面服务）的人员配置、劳动组织、服务标准及人力成本管理的通用理论与方法。", "boundary": "本节点聚焦于航空服务人员的组织管理与经济属性，包括服务流程优化、人员培训体系及服务质量对经济效益的影响。边界在于区分“人员管理/经济”与“具体操作技能”（如急救、烹饪等纯技能训练归入职业培训或具体服务流程，若树中无对应节点则视具体业务归属）及“纯工程技术”。", "includes": ["航空服务人员（乘务、地服）的劳动组织与排班理论", "服务岗位的人力成本分析与绩效考核体系", "服务质量标准及其对旅客满意度和收益的影响机制"], "excludes": ["纯飞行驾驶操作技术", "航空器机械维修技术"], "sibling_distinctions": [{"other_code": "N_9c809203afe730fb", "rule": "本节点侧重具体服务岗位的人员管理与服务经济；企业组织与经营管理理论侧重公司整体战略、组织架构及高层管理决策。"}, {"other_code": "N_9ae23662c114bf6f", "rule": "本节点侧重服务提供环节的人员与成本；运输业务侧重客货运输流程、票务处理及货物操作的业务逻辑。"}], "cross_boundary_rule": "涉及服务流程时，若侧重人员配置、成本或管理效率，归入本节点；若侧重具体服务动作规范或旅客体验设计，需视是否有专门服务设计节点，否则保留在本节点作为管理支撑。"}, {"node_code": "N_9907d4e610ba82dd", "definition": "研究航空公司通过动态定价、舱位控制、超售管理等手段最大化收益的通用理论、模型与算法，不局限于特定市场或公司。", "boundary": "本节点聚焦于收益管理（Revenue Management）的核心方法论，包括需求预测与定价联动、库存控制策略及收益优化模型。边界在于区分“收益管理”与“一般定价理论”（一般定价侧重成本加成或竞争定价，收益管理侧重基于需求弹性的动态库存优化）及“市场营销”（营销侧重品牌与渠道，收益管理侧重价格与库存的微观决策）。", "includes": ["动态定价与舱位控制（Seat Inventory Control）理论", "超售（Overbooking）策略与收益损失分析模型", "基于需求预测的收益优化算法与决策支持系统原理"], "excludes": ["航空运输一般成本核算与会计处理", "纯市场营销策略（如广告、品牌传播）"], "sibling_distinctions": [{"other_code": "N_01adb5e4e61607ad", "rule": "本节点侧重基于需求弹性的动态收益优化与库存控制；定价、成本与利润理论侧重静态成本结构、基础定价原则及利润核算方法。"}, {"other_code": "N_5289c021e39854dd", "rule": "本节点侧重价格与库存的微观经济决策；市场营销侧重市场细分、品牌定位、促销策略及客户关系管理。"}, {"other_code": "N_a9539a30081fdc3b", "rule": "本节点利用需求预测进行收益决策；需求预测侧重预测方法本身（如时间序列、回归模型）及预测精度评估，不直接涉及定价或库存策略。"}], "cross_boundary_rule": "涉及定价策略时，若核心在于利用需求预测进行舱位分配和动态调价以最大化收益，归入本节点；若侧重于基础成本加成定价或宏观价格管制政策，归入定价、成本与利润理论或相应政策节点。"}, {"node_code": "N_5289c021e39854dd", "definition": "研究航空运输市场的营销理论、策略、渠道管理及客户关系维护，涵盖市场细分、品牌定位、促销手段及数字化营销方法。", "boundary": "本节点聚焦于航空运输的营销职能，包括如何吸引和保留客户、品牌建设与市场推广。边界在于区分“市场营销”与“收益管理”（收益管理侧重价格与库存优化，营销侧重需求创造与品牌）及“一般管理”（侧重内部运营效率，营销侧重外部市场互动）。", "includes": ["航空运输市场细分、目标市场选择与品牌定位理论", "航空票务销售渠道管理、分销策略及代理体系分析", "客户关系管理（CRM）、忠诚度计划及数字化营销方法"], "excludes": ["基于需求预测的动态定价与舱位控制算法", "航空运输成本核算与财务审计"], "sibling_distinctions": [{"other_code": "N_9907d4e610ba82dd", "rule": "本节点侧重需求创造、品牌建设与渠道管理；收益管理侧重在既定需求下的价格优化与库存控制。"}, {"other_code": "N_a9539a30081fdc3b", "rule": "本节点利用需求预测制定营销策略；需求预测侧重预测模型与数据方法本身，不直接涉及营销战术或品牌策略。"}, {"other_code": "N_9c809203afe730fb", "rule": "本节点侧重外部市场互动与客户需求满足；企业组织与经营管理理论侧重内部组织架构、战略制定及资源分配。"}], "cross_boundary_rule": "涉及票价促销时，若侧重于广告、捆绑销售或品牌活动以刺激需求，归入本节点；若侧重于基于实时需求的动态价格调整算法，归入收益管理。"}]}
